import type { DeclaredVariable } from "@quickservice/core";
import { variableType } from "@quickservice/core";
import { existsSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";

export const ENV_EXAMPLE = ".env.example";
export const ENV_EXAMPLE_HEADER = "# Generated by quickservice build from quickservice.config.ts. Do not edit.";
export const HAND_WRITTEN_ENV_EXAMPLE = `${ENV_EXAMPLE} was not updated: it is not generated (it does not start with the quickservice header)`;

/** A default as written after `NAME=`: lists as comma-separated items, objects as JSON. */
function defaultText(value: unknown): string {
  if (typeof value === "string") return value;
  if (Array.isArray(value) && value.every((item) => typeof item !== "object" || item === null)) return value.join(",");
  if (typeof value === "object" && value !== null) return JSON.stringify(value);
  return String(value);
}

/** The content of `.env.example`: one commented block per variable; secrets and variables without a default stay empty. */
export function envExampleContent(variables: readonly DeclaredVariable[]): string {
  const blocks = variables.map(({ name, schema, owner }) => {
    const { settings } = schema;
    const secret = schema.kind === "secret";
    const lines = [
      ...(settings.description ? settings.description.split("\n").map((line) => `# ${line}`) : []),
      `# Type: ${variableType(schema)}`,
      settings.hasDefault ? `# default: ${defaultText(settings.default)}` : settings.optional ? "# optional" : "# required",
      ...(owner !== "the project" ? [`# Declared by: ${owner}`] : []),
      `${name}=${settings.hasDefault && !secret ? defaultText(settings.default) : ""}`,
    ];
    return lines.join("\n");
  });
  return `${[ENV_EXAMPLE_HEADER, ...blocks].join("\n\n")}\n`;
}

const isGenerated = (file: string) => readFileSync(file, "utf8").startsWith(ENV_EXAMPLE_HEADER);

/**
 * Writes `.env.example` at the project root when variables are declared and its content changed, and removes a
 * generated one when none are; a hand-written file (without the header) is never touched. Returns a warning when a
 * hand-written file kept the build from writing it.
 */
export function writeEnvExample(projectRoot: string, variables: readonly DeclaredVariable[]): string | undefined {
  const file = join(projectRoot, ENV_EXAMPLE);
  const exists = existsSync(file);
  if (variables.length === 0) {
    if (exists && isGenerated(file)) rmSync(file);
    return undefined;
  }
  if (exists && !isGenerated(file)) return HAND_WRITTEN_ENV_EXAMPLE;
  const content = envExampleContent(variables);
  if (!exists || readFileSync(file, "utf8") !== content) writeFileSync(file, content);
  return undefined;
}
